  check(cargo, ['--version'], /^cargo 1\.97\.1 /u); check(rustc, ['--version'], /^rustc 1\.97\.1 /u);
  check(input.RUSTDOC, ['--version'], /^rustdoc 1\.97\.1 /u);
  check(expectedClang, ['--version'], /^(?:Ubuntu |Debian )?clang version 18\.1\.3(?: |\n)/u);
  check(expectedCMake, ['--version'], /^cmake version 3\.31\.6(?:\n|$)/u);
  exactDirectory(expectedLibclang);
  if (!lstatSync(realpathSync(join(expectedLibclang, 'libclang.so.1'))).isFile()) throw new Error('SDK远端libclang缺失');
  check(input.PROTOC, ['--version'], /^libprotoc 35\.0$/u);
  check(input.PRODUCT_GIT_BIN, ['--version'], /^git version 2\.54\.0$/u);
  check(input.TATAGATE_ACTIONLINT, ['--version'], /^1\.7\.12(?:\n|$)/u);
  check(join(work, 'tools/solidity/bin/solc'), ['--version'], /\nVersion: 0\.8\.30\+commit\.73712a01\.Linux\.g\+\+$/u);
  check(join(work, 'tools/solidity/bin/resolc'), ['--version'], /^Solidity frontend for the revive compiler version 1\.0\.0\+commit\.[a-f0-9]+\.llvm-\d+\.\d+\.\d+$/u);
